SELECT CASE strftime('%m', p.birthdate) WHEN '01' THEN 'January' WHEN '02' THEN 'February' WHEN '03' THEN 'March' WHEN '04' THEN 'April' WHEN '05' THEN 'May' WHEN '06' THEN 'June' WHEN '07' THEN 'July' WHEN '08' THEN 'August' WHEN '09' THEN 'September' WHEN '10' THEN 'October' WHEN '11' THEN 'November' WHEN '12' THEN 'December' END AS "month of birth" FROM member AS m JOIN profiles AS p ON p.id = m.profile_id WHERE m.id BETWEEN 42 AND 84 ORDER BY m.id;
